<template><AppLayout v-if="!route.meta.public"><RouterView /></AppLayout><RouterView v-else /><Toast /></template>
<script setup lang="ts">import { onBeforeUnmount,onMounted } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import AppLayout from './components/layout/AppLayout.vue'; import Toast from './components/common/Toast.vue'; import { useAuthStore } from './stores/auth'; const route=useRoute(); const router=useRouter(); const auth=useAuthStore(); const onUnauthorized=()=>{auth.user=null;if(route.path!=='/login')void router.replace({path:'/login',query:{redirect:route.fullPath}})}; onMounted(()=>window.addEventListener('frp-panel:unauthorized',onUnauthorized)); onBeforeUnmount(()=>window.removeEventListener('frp-panel:unauthorized',onUnauthorized))</script>
